seen={}
for cat, s in raw.items():
 for name in s.split('|'):
  name=name.strip()
  if not name:continue
  key=name.casefold()
  if key not in seen:seen[key]=(name,cat)
# Add only plausible common market variants to reach exactly 500; skip duplicates.
variants={
 'Naan':['Plain','Butter','Garlic','Cheese','Chilli Garlic','Amritsari','Peshawari','Kalonji','Coriander','Tandoori'],
 'Dosa':['Plain','Masala','Mysore Masala','Rava','Onion Rava','Cheese','Paneer','Butter','Ghee Roast','Podi','Spring','Schezwan','Palak'],
 'Kulcha':['Plain','Aloo','Onion','Paneer','Cheese','Amritsari','Masala'],
 'Paratha':['Aloo','Gobi','Paneer','Mooli','Methi','Lachha','Mixed Veg','Cheese','Ajwain','Sattu','Dal'],
 'Uttapam':['Plain','Onion','Tomato','Vegetable','Cheese','Masala','Paneer','Podi'],
 'Momos':['Veg Steamed','Paneer Steamed','Chicken Steamed','Veg Fried','Chicken Fried','Veg Tandoori','Chicken Tandoori','Afghani Veg','Schezwan Veg'],
 'Tikka':['Paneer','Malai Paneer','Achari Paneer','Hariyali Paneer','Chicken','Malai Chicken','Mushroom','Soya Chaap','Tandoori Gobi'],
 'Lassi':['Sweet','Salted','Mango','Rose','Kesar','Pista','Strawberry','Dry Fruit','Chocolate','Banana'],
 'Pakora':['Onion','Paneer','Aloo','Palak','Bread','Gobi','Methi','Mixed Vegetable','Mirchi'],
 'Shake':['Chocolate','Vanilla','Strawberry','Mango','Banana','Oreo','KitKat','Dry Fruit','Coffee','Butterscotch'],
 'Halwa':['Gajar','Moong Dal','Sooji','Badam','Atta','Lauki','Beetroot','Pineapple','Pumpkin'],
 'Pulao':['Veg','Peas','Paneer','Mushroom','Kashmiri','Jeera','Corn','Mint','Soya'],
 'Biryani':['Vegetable','Paneer','Mushroom','Soya','Chicken','Egg','Mutton','Prawn','Fish','Hyderabadi Veg','Hyderabadi Chicken'],
}
catguess={'Naan':'North Indian','Dosa':'South Indian','Kulcha':'North Indian','Paratha':'North Indian','Uttapam':'South Indian','Momos':'Indo Chinese','Tikka':'North Indian','Lassi':'Drinks & Shakes','Pakora':'Street Food & Snacks','Shake':'Drinks & Shakes','Halwa':'Sweets & Desserts','Pulao':'Rice & Biryani','Biryani':'Rice & Biryani'}
for stem,prefixes in variants.items():
 for prefix in prefixes:
  name=(prefix+' '+stem).strip()
  if name.casefold() not in seen:seen[name.casefold()]=(name,catguess[stem])
# Very unusual oversupply? Prioritize base dishes, then common variants. 500 exact.
entries=list(seen.values());assert len(entries)>=500,len(entries)
entries=entries[:500]
def slug(name):return re.sub(r'-+','-',re.sub(r'[^a-z0-9]+','-',name.lower())).strip('-')
colors={'North Indian':('#BA693E','#F3C080','#D85036'),'South Indian':('#D2A44F','#E1C783','#D86832'),'Rice & Biryani':('#C69B3F','#F3DC9A','#9F612E'),'Street Food & Snacks':('#B98250','#F7D77D','#BA5339'),'Indo Chinese':('#AD4E2F','#EC9C50','#D46132'),'Sweets & Desserts':('#B67554','#F3CDA0','#DB9295'),'Drinks & Shakes':('#926655','#E5B78E','#9C653F'),'Other Regional':('#A67A3F','#E0C279','#A74D34')}
records=[]
folder=base/'public'/'assets'/'dishes';folder.mkdir(parents=True,exist_ok=True)
for n,(name,cat) in enumerate(entries):
 s=slug(name)
 # Decorative dish illustration, nonphotographic. Repeated visual vocabulary is intentional.
 rng=random.Random(int(hashlib.sha256(name.encode()).hexdigest()[:12],16))
 sauce,light,spice=colors[cat];p=[rng.randrange(60,440) for _ in range(14)]
 circles=''.join(f'<circle cx="{rng.randrange(115,386)}" cy="{rng.randrange(105,370)}" r="{rng.randrange(8,24)}" fill="{light if rng.random()>.5 else spice}" opacity=".76"/>' for i in range(16))
 leaves=''.join(f'<ellipse cx="{rng.randrange(125,377)}" cy="{rng.randrange(116,367)}" rx="{rng.randrange(4,9)}" ry="{rng.randrange(9,17)}" fill="#447F48" transform="rotate({rng.randrange(360)} 250 240)"/>' for i in range(12))
 text=html.escape(name)
 if len(text)>28:
  sp=text.split(' ');half=len(sp)//2;lines=[" ".join(sp[:half])," ".join(sp[half:])]
 else:lines=[text]
 tspan=''.join(f'<tspan x="250" dy="{0 if k==0 else 24}">{line}</tspan>' for k,line in enumerate(lines))
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="500" height="500" viewBox="0 0 500 500"><defs><radialGradient id="g"><stop stop-color="#fffaf0"/><stop offset="1" stop-color="#e6dac5"/></radialGradient><radialGradient id="a"><stop stop-color="{light}"/><stop offset="1" stop-color="{sauce}"/></radialGradient></defs><rect width="500" height="500" fill="#E6E1D5"/><path d="M0 0h500v500H0z" fill="url(#g)"/><circle cx="250" cy="242" r="195" fill="#b8aa93" opacity=".23"/><circle cx="250" cy="234" r="183" fill="#f9f7ed"/><circle cx="250" cy="234" r="166" fill="#e9e0d1"/><circle cx="250" cy="232" r="152" fill="url(#a)"/>{circles}{leaves}<circle cx="187" cy="161" r="16" fill="#fff0cc" opacity=".65"/><circle cx="337" cy="307" r="11" fill="#fff0cc" opacity=".55"/><rect x="20" y="395" width="460" height="85" rx="22" fill="#173D31" opacity=".96"/><text x="250" y="432" text-anchor="middle" font-family="Arial,sans-serif" fill="#FFF7E8" font-size="21" font-weight="bold">{tspan}</text><text x="250" y="467" text-anchor="middle" font-family="Arial,sans-serif" fill="#D3E7D3" font-size="11" letter-spacing="2">ILLUSTRATED MENU ART</text></svg>'''
 (folder/(s+'.svg')).write_text(svg,encoding='utf8')
 records.append({'name':name,'category':cat,'slug':s,'illustration':'assets/dishes/'+s+'.svg','photo_verified':False})
assert len({i['slug'] for i in records})==500
(base/'public'/'assets'/'dish_catalog.json').write_text(json.dumps(records,ensure_ascii=False,indent=2),encoding='utf8')
(base/'catalog'/'indian_dishes_500.json').write_text(json.dumps(records,ensure_ascii=False,indent=2),encoding='utf8')
(base/'catalog'/'PHOTO_LICENSE_README.md').write_text('''# Image and licensing notes\n\nThe **500 bundled SVG images are original generated menu illustrations, not photographs**, so do not present them to customers as photos of a real dish. `photo_verified: false` is intentional. They may be used as restaurant placeholders.\n\nFor photographic images, restaurant owners can upload their own photographs, or use the Wikimedia Commons suggestions in the Menu editor. Wikimedia image results include the creator, licence and original file page. Inspect relevance, attribution and licence requirements before publishing. Some photos may be unavailable.\n\nThe 500-item JSON file is a name autocomplete starter catalog. It is NOT 500 photo assets. Public domain/CC licensing cannot be assumed from a web image search.\n''',encoding='utf8')
print('created',len(records),'dish records & illustration SVGs')
